                <p className="text-sm text-slate-500 flex items-center gap-1.5 mt-1">
                  <Calendar className="w-4 h-4" /> Dibuat: {selectedQuotation.date} | Model Unit: {selectedQuotation.model_unit || 'SY215H'}
