﻿import { useState, useEffect, useMemo } from 'react';
import { getSpkSchedules } from '../services/api';

/**
 * Halaman Penjadwalan â€” daftar jadwal pekerjaan operasional berdasarkan SPK.
 *
 * Sumber data: GET /api/spk-schedules (data asli dari backend, tanpa dummy/localStorage).
 * Tahap 4D-1 hanya menampilkan data (read-only): belum ada form Tambah/Edit/Delete.
 */

/** Status lifecycle jadwal â€” mengikuti konstanta di backend. */
const SCHEDULE_STATUSES = ['SCHEDULED', 'IN_PROGRESS', 'DONE', 'POSTPONED', 'CANCELLED'];

/** Warna badge status, konsisten dengan pola halaman SPK. */
const statusBadge = (status) => {
    switch (status) {
        case 'SCHEDULED':
            return 'bg-blue-100 text-blue-800';
        case 'IN_PROGRESS':
            return 'bg-amber-100 text-amber-800';
        case 'DONE':
            return 'bg-emerald-100 text-emerald-800';
        case 'POSTPONED':
            return 'bg-orange-100 text-orange-800';
        case 'CANCELLED':
            return 'bg-rose-100 text-rose-800';
        default:
            return 'bg-slate-100 text-slate-700';
    }
};

export default function Scheduling() {
    const [schedules, setSchedules] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    // Filter dasar: pencarian teks & filter status (dilakukan di sisi klien).
    const [search, setSearch] = useState('');
    const [statusFilter, setStatusFilter] = useState('ALL');

    const fetchData = async () => {
        setLoading(true);
        setError(null);

        try {
            // Helper API resmi (token dilampirkan otomatis oleh interceptor di services/api.js).
            const res = await getSpkSchedules();
            const data = res.data?.data ?? res.data ?? [];
            setSchedules(Array.isArray(data) ? data : []);
        } catch (err) {
            console.error('Gagal mengambil data penjadwalan:', err);
            setError(
                err.response?.data?.message ||
                'Gagal mengambil data penjadwalan. Pastikan server backend berjalan dan Anda memiliki akses.'
            );
            setSchedules([]);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    /** Format tanggal Indonesia yang mudah dibaca, mis. "30 Sep 2026". */
    const formatDate = (value) => {
        if (!value) return '-';
        const date = new Date(value);
        if (isNaN(date.getTime())) return value;
        return date.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
    };

    /** Gabungkan jam mulai & selesai; "-" bila keduanya kosong. */
    const formatTime = (start, end) => {
        const s = start ? String(start).substring(0, 5) : '';
        const e = end ? String(end).substring(0, 5) : '';
        if (!s && !e) return '-';
        if (s && e) return `${s} - ${e}`;
        return s || e;
    };

    /** Kumpulkan nama personel dari relasi assignments.employee.employee_name. */
    const getPersonnel = (schedule) => {
        const assignments = Array.isArray(schedule.assignments) ? schedule.assignments : [];
        const names = assignments
            .map((a) => a?.employee?.employee_name)
            .filter(Boolean);
        return names;
    };

    /** Normalisasi progress ke persen 0-100 untuk tampilan. */
    const getProgress = (value) => {
        const num = Number(value);
        if (isNaN(num)) return 0;
        // Mendukung nilai 0-100 maupun 0-1 (rasio).
        const pct = num <= 1 && num > 0 ? num * 100 : num;
        return Math.max(0, Math.min(100, Math.round(pct)));
    };

    /* â”€â”€ Filter data di sisi klien â”€â”€ */
    const filtered = useMemo(() => {
        const q = search.trim().toLowerCase();

        return schedules.filter((s) => {
            // Filter status.
            if (statusFilter !== 'ALL' && (s.status || '') !== statusFilter) return false;

            if (!q) return true;

            // Pencarian pada field utama + relasi SPK.
            const haystack = [
                s.schedule_code,
                s.spk?.spk_number,
                s.spk?.project_name,
                s.spk?.serial_no,
                s.activity,
            ]
                .filter(Boolean)
                .join(' ')
                .toLowerCase();

            return haystack.includes(q);
        });
    }, [schedules, search, statusFilter]);

    const columnCount = 12;

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800">Penjadwalan</h1>
                    <p className="text-sm text-slate-500">Jadwal pekerjaan operasional berdasarkan SPK</p>
                </div>
                <div className="flex items-center gap-2">
                    <button
                        onClick={fetchData}
                        disabled={loading}
                        className="bg-slate-700 hover:bg-slate-800 disabled:bg-slate-400 text-white px-4 py-2 rounded-lg font-medium transition cursor-pointer disabled:cursor-not-allowed"
                    >
                        {loading ? 'Memuat...' : 'Muat Ulang'}
                    </button>
                </div>
            </div>

            {error && (
                <div className="mb-4 p-4 rounded-xl border border-rose-200 bg-rose-50 text-rose-700 text-sm flex justify-between items-center gap-4">
                    <span>{error}</span>
                    <button
                        onClick={fetchData}
                        className="bg-rose-600 hover:bg-rose-700 text-white px-3 py-1.5 rounded text-xs font-medium cursor-pointer transition whitespace-nowrap"
                    >
                        Coba Lagi
                    </button>
                </div>
            )}

            {/* â”€â”€â”€ Filter dasar: Search & Status â”€â”€â”€ */}
            <div className="flex flex-col sm:flex-row gap-3 mb-4">
                <input
                    type="text"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    placeholder="Cari kode jadwal, No. SPK, project, aktivitas..."
                    className="flex-1 border rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-400 bg-white"
                />
                <select
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value)}
                    className="sm:w-56 border rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-400 bg-white"
                >
                    <option value="ALL">Semua Status</option>
                    {SCHEDULE_STATUSES.map((s) => (
                        <option key={s} value={s}>{s}</option>
                    ))}
                </select>
            </div>

            <div className="bg-white rounded-xl shadow-sm overflow-x-auto border border-slate-100">
                <table className="w-full text-left border-collapse min-w-[1400px]">
                    <thead>
                        <tr className="bg-slate-50 text-slate-600 text-xs uppercase tracking-wider border-b">
                            <th className="p-4">No.</th>
                            <th className="p-4">Kode Jadwal</th>
                            <th className="p-4">No. SPK</th>
                            <th className="p-4">Project</th>
                            <th className="p-4">Aktivitas</th>
                            <th className="p-4">Tanggal Rencana</th>
                            <th className="p-4">Jam</th>
                            <th className="p-4">Lokasi</th>
                            <th className="p-4">Personel</th>
                            <th className="p-4">Prioritas</th>
                            <th className="p-4">Progress</th>
                            <th className="p-4">Status</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 text-sm">
                        {loading ? (
                            <tr>
                                <td colSpan={columnCount} className="p-4 text-center text-slate-400">Memuat data penjadwalan...</td>
                            </tr>
                        ) : error ? (
                            <tr>
                                <td colSpan={columnCount} className="p-4 text-center text-rose-500">Gagal memuat data. Silakan coba lagi.</td>
                            </tr>
                        ) : filtered.length === 0 ? (
                            <tr>
                                <td colSpan={columnCount} className="p-4 text-center text-slate-400">
                                    {schedules.length === 0
                                        ? 'Belum ada data penjadwalan.'
                                        : 'Tidak ada data yang sesuai filter.'}
                                </td>
                            </tr>
                        ) : (
                            filtered.map((schedule, index) => {
                                const personnel = getPersonnel(schedule);
                                const progress = getProgress(schedule.progress);

                                return (
                                    <tr key={schedule.id ?? index} className="hover:bg-slate-50 align-top">
                                        <td className="p-4 text-slate-500">{index + 1}</td>
                                        <td className="p-4 font-semibold text-slate-700">{schedule.schedule_code || '-'}</td>
                                        <td className="p-4">{schedule.spk?.spk_number || '-'}</td>
                                        <td className="p-4">{schedule.spk?.project_name || '-'}</td>
                                        <td className="p-4">{schedule.activity || '-'}</td>
                                        <td className="p-4">{formatDate(schedule.planned_date)}</td>
                                        <td className="p-4 whitespace-nowrap">
                                            {formatTime(schedule.planned_start_time, schedule.planned_end_time)}
                                        </td>
                                        <td className="p-4">{schedule.location || '-'}</td>
                                        <td className="p-4">
                                            {personnel.length === 0 ? (
                                                '-'
                                            ) : (
                                                <div className="flex flex-col gap-0.5">
                                                    {personnel.map((name, i) => (
                                                        <span key={i} className="text-slate-700">{name}</span>
                                                    ))}
                                                </div>
                                            )}
                                        </td>
                                        <td className="p-4">{schedule.priority || '-'}</td>
                                        <td className="p-4">
                                            <div className="flex items-center gap-2">
                                                <div className="w-20 h-1.5 bg-slate-200 rounded-full overflow-hidden">
                                                    <div
                                                        className="h-full bg-emerald-500 rounded-full"
                                                        style={{ width: `${progress}%` }}
                                                    />
                                                </div>
                                                <span className="text-xs text-slate-600 whitespace-nowrap">{progress}%</span>
                                            </div>
                                        </td>
                                        <td className="p-4">
                                            <span className={`px-2.5 py-1 text-xs font-semibold rounded-full ${statusBadge(schedule.status)}`}>
                                                {schedule.status || '-'}
                                            </span>
                                        </td>
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

import { useCallback, useEffect, useState } from 'react';
import { ClipboardCheck, RefreshCw, Save } from 'lucide-react';
import { completeStockOpname, createStockOpname, getProducts, getStockOpnames, getWarehouses } from '../services/api';
import Pagination from '../components/Pagination';
import usePagination from '../hooks/usePagination';

export default function StockOpname() {
  const [rows, setRows] = useState([]);
  const [products, setProducts] = useState([]);
  const [warehouses, setWarehouses] = useState([]);
  const [form, setForm] = useState({
    document_number: '',
    opname_date: new Date().toISOString().slice(0, 10),
    warehouse_id: '',
    items: []
  });
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [saving, setSaving] = useState(false);

  const pagination = usePagination(rows, 10);

  const load = useCallback(async () => {
    try {
      const [o, p, w] = await Promise.all([getStockOpnames(), getProducts(), getWarehouses()]);
      setRows(o.data?.data || []);
      setProducts(p.data?.data || []);
      setWarehouses(w.data?.data || []);
    } catch (e) {
      setError(e.response?.data?.message || 'Data stock opname gagal dimuat.');
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const addItem = () =>
    setForm((prev) => ({
      ...prev,
      items: [...prev.items, { product_id: '', physical_quantity: 0, notes: '' }]
    }));

  const updateItem = (index, key, value) =>
    setForm((prev) => ({
      ...prev,
      items: prev.items.map((item, i) => (i === index ? { ...item, [key]: value } : item))
    }));

  const submit = async (e) => {
    e.preventDefault();
    setSaving(true);
    setError('');
    setMessage('');
    try {
      await createStockOpname({
        ...form,
        items: form.items.map((item) => ({
          ...item,
          product_id: Number(item.product_id),
          physical_quantity: Number(item.physical_quantity)
        }))
      });
      setMessage('Stock opname berhasil dibuat sebagai DRAFT.');
      setForm({
        document_number: '',
        opname_date: new Date().toISOString().slice(0, 10),
        warehouse_id: '',
        items: []
      });
      await load();
    } catch (err) {
      setError(err.response?.data?.message || 'Stock opname gagal dibuat.');
    } finally {
      setSaving(false);
    }
  };

  const complete = async (id) => {
    if (!window.confirm('Selesaikan stock opname dan lakukan adjustment?')) return;
    try {
      await completeStockOpname(id);
      setMessage('Stock opname selesai dan adjustment tercatat.');
      await load();
    } catch (e) {
      setError(e.response?.data?.message || 'Stock opname gagal diselesaikan.');
    }
  };

  return (
    <div className="p-6 max-w-7xl mx-auto w-full space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Stock Opname</h2>
          <p className="text-sm text-slate-500">Bandingkan stok sistem dengan stok fisik tanpa menghilangkan histori.</p>
        </div>
        <button onClick={load} className="p-2 border rounded-lg hover:bg-slate-50 transition cursor-pointer">
          <RefreshCw className="w-4 h-4" />
        </button>
      </div>

      {error && <div className="p-3 rounded-lg bg-red-50 text-red-700 text-sm">{error}</div>}
      {message && <div className="p-3 rounded-lg bg-emerald-50 text-emerald-700 text-sm">{message}</div>}

      <form onSubmit={submit} className="bg-white border rounded-2xl p-5 shadow-sm space-y-4">
        <div className="grid md:grid-cols-3 gap-3">
          <input
            required
            placeholder="Nomor dokumen"
            value={form.document_number}
            onChange={(e) => setForm({ ...form, document_number: e.target.value })}
            className="border rounded-lg px-3 py-2 text-sm"
          />
          <input
            required
            type="date"
            value={form.opname_date}
            onChange={(e) => setForm({ ...form, opname_date: e.target.value })}
            className="border rounded-lg px-3 py-2 text-sm"
          />
          <select
            required
            value={form.warehouse_id}
            onChange={(e) => setForm({ ...form, warehouse_id: e.target.value })}
            className="border rounded-lg px-3 py-2 text-sm"
          >
            <option value="">Pilih warehouse</option>
            {warehouses.map((w) => (
              <option key={w.id} value={w.id}>
                {w.code} — {w.name}
              </option>
            ))}
          </select>
        </div>

        {form.items.map((item, index) => (
          <div key={index} className="grid md:grid-cols-3 gap-3">
            <select
              required
              value={item.product_id}
              onChange={(e) => updateItem(index, 'product_id', e.target.value)}
              className="border rounded-lg px-3 py-2 text-sm"
            >
              <option value="">Pilih item</option>
              {products.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.part_number || p.product_code} — {p.name}
                </option>
              ))}
            </select>
            <input
              required
              min="0"
              type="number"
              value={item.physical_quantity}
              onChange={(e) => updateItem(index, 'physical_quantity', e.target.value)}
              placeholder="Stok fisik"
              className="border rounded-lg px-3 py-2 text-sm"
            />
            <input
              value={item.notes}
              onChange={(e) => updateItem(index, 'notes', e.target.value)}
              placeholder="Keterangan"
              className="border rounded-lg px-3 py-2 text-sm"
            />
          </div>
        ))}

        <div className="flex gap-2">
          <button type="button" onClick={addItem} className="px-4 py-2 border rounded-lg text-sm hover:bg-slate-50 cursor-pointer">
            Tambah Item
          </button>
          <button
            disabled={saving || !form.items.length}
            className="px-4 py-2 rounded-lg bg-blue-600 text-white text-sm flex gap-2 items-center disabled:opacity-60 hover:bg-blue-700 transition cursor-pointer"
          >
            <Save className="w-4 h-4" />
            Simpan Draft
          </button>
        </div>
      </form>

      <div className="bg-white border rounded-2xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="p-3 text-left font-semibold text-slate-600">Dokumen</th>
                <th className="p-3 text-left font-semibold text-slate-600">Tanggal</th>
                <th className="p-3 text-left font-semibold text-slate-600">Warehouse</th>
                <th className="p-3 text-left font-semibold text-slate-600">Status</th>
                <th className="p-3 text-center font-semibold text-slate-600">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {pagination.totalItems === 0 ? (
                <tr>
                  <td colSpan="5" className="p-8 text-center text-slate-400">
                    Belum ada stock opname.
                  </td>
                </tr>
              ) : (
                pagination.paginatedItems.map((row) => (
                  <tr key={row.id} className="hover:bg-slate-50 transition">
                    <td className="p-3 font-mono text-slate-700">{row.document_number}</td>
                    <td className="p-3 text-slate-600">{row.opname_date}</td>
                    <td className="p-3 text-slate-600">{row.warehouse?.name || '-'}</td>
                    <td className="p-3">
                      <span className={`inline-flex px-2.5 py-1 rounded-full text-xs font-semibold ${
                        row.status === 'COMPLETED' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'
                      }`}>
                        {row.status}
                      </span>
                    </td>
                    <td className="p-3 text-center">
                      {row.status === 'DRAFT' && (
                        <button
                          onClick={() => complete(row.id)}
                          className="text-blue-600 hover:text-blue-800 transition p-1 hover:bg-blue-50 rounded"
                          title="Selesaikan Opname"
                        >
                          <ClipboardCheck className="w-4 h-4" />
                        </button>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
        <Pagination
          currentPage={pagination.currentPage}
          totalItems={pagination.totalItems}
          pageSize={pagination.pageSize}
          onPageChange={pagination.setCurrentPage}
          onPageSizeChange={pagination.setPageSize}
        />
      </div>
    </div>
  );
}

